def find_diamonds(a):
    # complete plus: center c with 4 orthogonal neighbors ==2
    pts=set(map(tuple,np.argwhere(a==2)))
    res=[]
    for r in range(a.shape[0]-1):
        for c in range(a.shape[1]-1):
            nb={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
            if nb<=pts: res.append((r,c,nb))
    return res

